const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length);
const n = Number(tok[0]), q = Number(tok[1]);
const val = [];
for (let i = 0; i < n; i++) val.push(Number(tok[2 + i]));
const adj = Array.from({ length: n }, () => []);
let p = 2 + n;
for (let i = 0; i < n - 1; i++) {
  const u = Number(tok[p]) - 1, v = Number(tok[p + 1]) - 1;
  p += 2;
  adj[u].push(v); adj[v].push(u);
}
const parent = new Array(n).fill(-1), depth = new Array(n).fill(0), order = [];
const stack = [0];
while (stack.length) {
  const u = stack.pop();
  order.push(u);
  for (const v of adj[u]) if (v !== parent[u]) { parent[v] = u; depth[v] = depth[u] + 1; stack.push(v); }
}
const size = new Array(n).fill(1), heavy = new Array(n).fill(-1);
for (let i = n - 1; i >= 0; i--) {
  const u = order[i], par = parent[u];
  if (par >= 0) {
    size[par] += size[u];
    if (heavy[par] === -1 || size[u] > size[heavy[par]]) heavy[par] = u;
  }
}
const head = new Array(n).fill(0), pos = new Array(n).fill(0);
let cur = 0;
for (const u of order) {
  if (parent[u] === -1 || heavy[parent[u]] !== u) {
    for (let v = u; v !== -1; v = heavy[v]) { head[v] = u; pos[v] = cur++; }
  }
}
const NEG = -1e18;
const tree = new Array(2 * n).fill(NEG);
for (let u = 0; u < n; u++) tree[n + pos[u]] = val[u];
for (let i = n - 1; i >= 1; i--) tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
function update(i, x) {
  i += n; tree[i] = x;
  for (i >>= 1; i >= 1; i >>= 1) tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
}
function query(l, r) {
  let res = NEG;
  l += n; r += n + 1;
  while (l < r) {
    if (l & 1) res = Math.max(res, tree[l++]);
    if (r & 1) res = Math.max(res, tree[--r]);
    l >>= 1; r >>= 1;
  }
  return res;
}
const out = [];
for (let i = 0; i < q; i++) {
  if (tok[p] === "1") {
    update(pos[Number(tok[p + 1]) - 1], Number(tok[p + 2]));
  } else {
    let u = Number(tok[p + 1]) - 1, v = Number(tok[p + 2]) - 1;
    let res = NEG;
    while (head[u] !== head[v]) {
      if (depth[head[u]] < depth[head[v]]) { const t = u; u = v; v = t; }
      res = Math.max(res, query(pos[head[u]], pos[u]));
      u = parent[head[u]];
    }
    if (depth[u] > depth[v]) { const t = u; u = v; v = t; }
    res = Math.max(res, query(pos[u], pos[v]));
    out.push(res);
  }
  p += 3;
}
console.log(out.join("\n"));

