import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static long[] tree;
    static final long NEG = Long.MIN_VALUE / 4;

    static void update(int i, long x) {
        i += n;
        tree[i] = x;
        for (i >>= 1; i >= 1; i >>= 1) tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
    }

    static long query(int l, int r) {
        long res = NEG;
        l += n;
        r += n + 1;
        while (l < r) {
            if ((l & 1) == 1) res = Math.max(res, tree[l++]);
            if ((r & 1) == 1) res = Math.max(res, tree[--r]);
            l >>= 1;
            r >>= 1;
        }
        return res;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        long[] val = new long[n];
        for (int i = 0; i < n; i++) { in.nextToken(); val[i] = (long) in.nval; }
        ArrayList<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            in.nextToken(); int u = (int) in.nval - 1;
            in.nextToken(); int v = (int) in.nval - 1;
            adj[u].add(v);
            adj[v].add(u);
        }
        int[] parent = new int[n], depth = new int[n], order = new int[n];
        Arrays.fill(parent, -1);
        int cnt = 0;
        int[] stack = new int[n];
        int sp = 0;
        stack[sp++] = 0;
        while (sp > 0) {
            int u = stack[--sp];
            order[cnt++] = u;
            for (int v : adj[u]) {
                if (v != parent[u]) { parent[v] = u; depth[v] = depth[u] + 1; stack[sp++] = v; }
            }
        }
        int[] size = new int[n], heavy = new int[n];
        Arrays.fill(size, 1);
        Arrays.fill(heavy, -1);
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i], par = parent[u];
            if (par >= 0) {
                size[par] += size[u];
                if (heavy[par] == -1 || size[u] > size[heavy[par]]) heavy[par] = u;
            }
        }
        int[] head = new int[n], pos = new int[n];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            int u = order[i];
            if (parent[u] == -1 || heavy[parent[u]] != u) {
                for (int v = u; v != -1; v = heavy[v]) { head[v] = u; pos[v] = cur++; }
            }
        }
        tree = new long[2 * n];
        Arrays.fill(tree, NEG);
        for (int u = 0; u < n; u++) tree[n + pos[u]] = val[u];
        for (int i = n - 1; i >= 1; i--) tree[i] = Math.max(tree[2 * i], tree[2 * i + 1]);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            int type = (int) in.nval;
            in.nextToken();
            int a = (int) in.nval - 1;
            in.nextToken();
            if (type == 1) {
                update(pos[a], (long) in.nval);
            } else {
                int b = (int) in.nval - 1;
                long res = NEG;
                while (head[a] != head[b]) {
                    if (depth[head[a]] < depth[head[b]]) { int t = a; a = b; b = t; }
                    res = Math.max(res, query(pos[head[a]], pos[a]));
                    a = parent[head[a]];
                }
                if (depth[a] > depth[b]) { int t = a; a = b; b = t; }
                res = Math.max(res, query(pos[a], pos[b]));
                out.append(res).append('\n');
            }
        }
        System.out.print(out);
    }
}

