#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n;
vector<ll> tr;
const ll NEG = LLONG_MIN / 4;

void update(int i, ll x) {
    i += n;
    tr[i] = x;
    for (i >>= 1; i >= 1; i >>= 1) tr[i] = max(tr[2 * i], tr[2 * i + 1]);
}
ll query(int l, int r) {
    ll res = NEG;
    l += n; r += n + 1;
    while (l < r) {
        if (l & 1) res = max(res, tr[l++]);
        if (r & 1) res = max(res, tr[--r]);
        l >>= 1; r >>= 1;
    }
    return res;
}
int main() {
    int q;
    scanf("%d %d", &n, &q);
    vector<ll> val(n);
    for (auto& x : val) scanf("%lld", &x);
    vector<vector<int>> adj(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> parent(n, -1), depth(n, 0), order, st = {0};
    while (!st.empty()) {
        int u = st.back(); st.pop_back();
        order.push_back(u);
        for (int v : adj[u])
            if (v != parent[u]) { parent[v] = u; depth[v] = depth[u] + 1; st.push_back(v); }
    }
    vector<int> sz(n, 1), heavy(n, -1);
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i], par = parent[u];
        if (par >= 0) {
            sz[par] += sz[u];
            if (heavy[par] == -1 || sz[u] > sz[heavy[par]]) heavy[par] = u;
        }
    }
    vector<int> head(n), pos(n);
    int cur = 0;
    for (int u : order)
        if (parent[u] == -1 || heavy[parent[u]] != u)
            for (int v = u; v != -1; v = heavy[v]) { head[v] = u; pos[v] = cur++; }
    tr.assign(2 * n, NEG);
    for (int u = 0; u < n; u++) tr[n + pos[u]] = val[u];
    for (int i = n - 1; i >= 1; i--) tr[i] = max(tr[2 * i], tr[2 * i + 1]);
    while (q--) {
        int t, a, b;
        scanf("%d %d %d", &t, &a, &b);
        a--;
        if (t == 1) {
            update(pos[a], b);
        } else {
            b--;
            ll res = NEG;
            while (head[a] != head[b]) {
                if (depth[head[a]] < depth[head[b]]) swap(a, b);
                res = max(res, query(pos[head[a]], pos[a]));
                a = parent[head[a]];
            }
            if (depth[a] > depth[b]) swap(a, b);
            res = max(res, query(pos[a], pos[b]));
            printf("%lld\n", res);
        }
    }
    return 0;
}
